"""Generate ``docs/checks.md`` from the check registry and crosswalk."""

from __future__ import annotations

from mcp_crosswalk.checks.registry import ALL_CHECKS
from mcp_crosswalk.crosswalk import load_crosswalk, load_owasp_catalog
from mcp_crosswalk.models import DISCLAIMER


def render_checks_markdown() -> str:
    crosswalk = load_crosswalk()
    titles = {r.short_id: r.title for r in load_owasp_catalog().risks}
    lines = [
        "# Static checks",
        "",
        "<!-- GENERATED by `mcpxw checks list --format md`. Do not hand-edit. -->",
        "",
        f"> {DISCLAIMER}",
        "",
        "The scanner reads MCP client config files as JSON and never runs, installs, or connects "
        "to anything they name. Each check below produces findings joined to the crosswalk "
        "mappings that cite it.",
        "",
        "| ID | Title | Risks | Severity |",
        "|---|---|---|---|",
    ]
    for check in ALL_CHECKS:
        lines.append(
            f"| {check.id} | {check.title} | {', '.join(check.risk_ids)} | {check.severity} |"
        )
    lines.append("")
    for check in ALL_CHECKS:
        risks = "; ".join(f"{r} ({titles.get(r, '')})" for r in check.risk_ids)
        lines += [
            f"## {check.id}: {check.title}",
            "",
            f"- Risks: {risks}",
            f"- Default severity: {check.severity}",
        ]
        if check.requires_allowlist:
            lines.append("- Runs only when `--allowlist FILE` is given")
        lines += ["", check.description, "", f"**Remediation.** {check.remediation}", ""]
        lines += ["**Mapped controls** (crosswalk mappings that cite this check):", ""]
        for risk_id in check.risk_ids:
            for mapping in crosswalk[risk_id].mappings:
                if check.id in mapping.check_ids:
                    lines.append(
                        f"- {risk_id} / {mapping.framework} `{mapping.control_id}` "
                        f"({mapping.relationship}, {mapping.confidence} confidence)"
                    )
        lines.append("")
    return "\n".join(lines)
